    DataLineOrNoStatement ("EXIT.")
  }
  If ((CompareTypeSafe (GetSgsValue ("PARAM,$I,1,1")) "EqualTo" "COND")) {
    $PARAMOLD = "C"
  } else {
    $PARAMOLD = " "
  }
}
